#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$ROOT"
TMP="$(mktemp)"
trap 'rm -f "$TMP"' EXIT
bash scripts/local/supabase.sh status -o env > "$TMP"
# This source is generated by our local Supabase CLI, not user input.
set -a
# shellcheck source=/dev/null
source "$TMP"
set +a
: "${API_URL:?Supabase API_URL missing}"
KEY="${PUBLISHABLE_KEY:-${ANON_KEY:-}}"
ADMIN="${SECRET_KEY:-${SERVICE_ROLE_KEY:-}}"
if [[ -z "$KEY" || -z "$ADMIN" ]]; then
  echo "Local Supabase publishable/anon or secret/service_role key missing" >&2
  exit 1
fi
if [[ -f ".env.local" && "${1:-}" != "--force" ]]; then
  local_url="$(sed -n 's/^SUPABASE_URL="\([^"]*\)"/\1/p' .env.local)"
  case "$local_url" in
    http://127.0.0.1:*|http://localhost:*)
      echo ".env.local already targets localhost; preserving existing local credentials."
      exit 0 ;;
    *)
      echo "Existing .env.local does not point to local Supabase. Use bash scripts/local/env.sh --force to replace it." >&2
      exit 1 ;;
  esac
fi
umask 077
CRON="$(openssl rand -hex 32)"
cat > ".env.local" <<ENVFILE
# Generated for LOCAL ONLY. Do not commit.
VITE_SUPABASE_URL="${API_URL}"
VITE_SUPABASE_PUBLISHABLE_KEY="${KEY}"
SUPABASE_URL="${API_URL}"
SUPABASE_PUBLISHABLE_KEY="${KEY}"
SUPABASE_SERVICE_ROLE_KEY="${ADMIN}"
TRADE_OS_CRON_SECRET="${CRON}"
VITE_ENABLE_GOOGLE_OAUTH="false"
# Optional: local Ollama, no data ever sent to Lovable.
# AI_API_BASE_URL="http://127.0.0.1:11434/v1"
# AI_MODEL="qwen3:4b"
# AI_API_KEY=""
ENVFILE
chmod 600 .env.local
echo "Wrote private .env.local for Supabase on ${API_URL}; no credentials were displayed."
